'use strict';
const CRAFT_UI5={bind,coffeeView,roastersView,estatesView,labView,performanceView,supplyView,help};
TITLES.craft='Vlastní původ & pražení';
let craftBlend5=state.blends[0].id,craftRoaster5=state.roasters[0].id;
function currentCraft5(){return {b:blend(craftBlend5)||state.blends[0],r:state.roasters.find(r=>r.id===craftRoaster5)||state.roasters[0]};}
function flavorBars5(f){return `<div class="craft-flavors5">${Object.entries(FLAVOR_KEYS5).map(([k,label])=>`<div><span>${label}</span><div class="bar"><i style="width:${f[k]}%"></i></div><strong>${number(f[k],0)}</strong></div>`).join('')}</div>`;}
function sourceLabel5(s){return s.known?s.name+' · '+VARIETIES5[s.variety].name+' · '+PROCESSES5[s.process].name:s.name+' · odrůda a zpracování nezaznamenány';}
function sourceOptions5(origin,selected){return option('any','Libovolná zásoba původu',selected)+state.estates.filter(e=>e.origin===origin).map(e=>option(e.id,e.name+' · sklizeň vlastní plantáže',selected)).join('');}
function profileCurve5(p){if(!p)return '<p class="sub">Původní profil receptury: bez individuálních parametrů.</p>';const x=60+p.minutes/18*470,y=235-(p.drop-80)/160*185,start=x-(x-60)*p.development/100;return `<svg class="craft-profile5" viewBox="0 0 590 285" role="img" aria-label="Schematický herní profil: ${p.minutes} minut, konečná teplota ${p.drop} stupňů, development ${p.development} procent"><path d="M60 40V235H545" stroke="#bdc5b7" fill="none"/><path d="M60 60L${60+(x-60)*.12} 220 Q${60+(x-60)*.52} 150 ${start} ${y+28}L${x} ${y}" stroke="#264b3b" stroke-width="4" fill="none"/><rect x="${start}" y="40" width="${x-start}" height="195" fill="#bd7643" opacity=".12"/><text x="15" y="53" font-size="12">°C</text><text x="35" y="235" font-size="11">80</text><text x="25" y="60" font-size="11">230</text><text x="58" y="257" font-size="11">0 min</text><text x="${x-30}" y="257" font-size="11">${p.minutes} min</text><text x="${Math.min(x,440)}" y="${y-8}" font-size="12">${p.drop} °C</text><text x="310" y="279" font-size="11">Development ${p.development} % · schematický průběh</text></svg>`;}
function craftView(){const {b,r}=currentCraft5();craftBlend5=b.id;craftRoaster5=r.id;const sources=craftSourcing5(b),stored=roastProfile5(r,b),p=stored||{drop:[0,201,211,224][b.roast],minutes:12,development:20};return `<div class="view-toolbar"><p class="intro">Vytvoř vlastní kávu od porostu po šálek. Volby mění fyzické šarže, náklady a přijetí hosty. Starší sklizně a zásoby drží svůj původní příběh.</p><div class="fields">${field('Káva',`<select id="craftBlend5">${blendOptions(b.id)}</select>`)}${field('Pražírna',`<select id="craftRoaster5">${state.roasters.map(x=>option(x.id,x.name+' · '+x.zone,r.id)).join('')}</select>`)}</div></div><div class="report-overview5">${metric('VLASTNÍ PLANTÁŽE',state.estates.length,'Odrůda a zpracování se řídí na plantáži')}${metric('ZELENÁ ZRNA',number(state.green.reduce((a,g)=>a+g.kg,0),1)+' kg',state.shipments.length+' dodávek na cestě')}${metric('PROFILY PRAŽENÍ',state.roasters.reduce((a,r)=>a+Object.keys(r.profiles5||{}).length,0),'Samostatně pro každou pražírnu a kávu')}${metric('HISTORIE ŠARŽÍ',state.craft5.ledger.length,'Posledních 200 nově upražených šarží')}</div><div class="split"><section class="card"><h2>${esc(b.name)} · původ zrn</h2><p class="sub">Poměr ${b.share} % ${esc(ORIGINS[b.primary].name)} / ${100-b.share} % ${esc(ORIGINS[b.secondary].name)}. Nejprve uprav recepturu, pokud chceš jiný původ.</p><div class="fields">${field('Hlavní původ',`<select id="craftPrimary5">${sourceOptions5(b.primary,sources.primarySource)}</select>`)}${field('Doplňkový původ',`<select id="craftSecondary5">${sourceOptions5(b.secondary,sources.secondarySource)}</select>`)}</div><label class="checkbox-line"><input id="craftFallback5" type="checkbox" ${sources.fallback?'checked':''}> Povolit jiné zásoby stejného původu při nedostatku vlastní sklizně</label><button class="primary" id="craftSourcesSave5">Uložit pravidla původu</button><button class="soft" data-goto="estates">Pěstování & zpracování</button><p class="sub">Povinná vlastní sklizeň omezí velikost dávky na dostupná zrna; prázdná zásoba pozastaví pražení. Zásilky, které ještě nepřijely, se nedají použít. Při povolené náhradě má vlastní sklizeň přednost; skutečný poměr v šarži se zaznamená.</p></section><section class="card"><h2>${esc(r.name)} · profil pro tuto kávu</h2><label class="checkbox-line"><input id="craftProfileEnabled5" type="checkbox" ${stored?'checked':''}> Použít individuální profil místo stupně pražení receptury</label><div class="fields">${field('Konečná teplota (°C)',input('craftDrop5',p.drop,185,230))}${field('Celkový čas (min)',input('craftMinutes5',p.minutes,8,18))}${field('Development (%)',input('craftDevelopment5',p.development,10,30))}</div>${profileCurve5(stored)}<div class="actions"><button class="primary" id="craftProfileSave5">Uložit profil</button><button class="quiet" id="craftProfileReset5">Vrátit profil receptury</button></div><p class="sub">Do 204 °C světlé, 205–216 °C střední, od 217 °C tmavé pražení. Delší čas zabere více kapacity; teplota a development mění chuť, výtěžnost a cenu zpracování. Čísla i křivka jsou zjednodušený herní model.</p></section></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Ověř šarži před výrobou</h2><span class="badge">Náhled nemění hru</span></div><div class="fields">${field('Zelená káva do šarže (kg)',input('craftKg5',10,1,2000))}<div class="actions"><button class="soft" id="craftPreview5">Porovnat nastavený profil</button><button class="primary" id="craftRoast5">Pražit podle uložených pravidel</button></div></div><p class="sub">Porovnání použije hodnoty formuláře a skutečné dostupné zásoby v kopii firmy. Výroba používá uložené nastavení; změny nejprve ulož. Při nedostatku kapacity, zrn nebo peněz se celý návrh odmítne. Přepravu kávy řídí sklady a trasy.</p></section><div class="section-header"><h2>Zelené šarže & přicházející sklizně</h2><button class="soft" data-goto="supply">Výhled zásobování</button></div><section class="card"><div class="table-scroll"><table class="data"><thead><tr><th scope="col">Původ / sklizeň</th><th scope="col">Množství</th><th scope="col">Náklad / kg</th><th scope="col">Kvalita</th><th scope="col">Dostupnost</th></tr></thead><tbody>${[...state.green.map(g=>({...g,due:null})),...state.shipments].map(g=>`<tr><td><strong>${esc(ORIGINS[g.origin].name)}</strong><small>${esc(g.source5?sourceLabel5(g.source5):'Dodavatelská zásoba · podrobnosti nezaznamenány')}</small></td><td>${number(g.kg,1)} kg</td><td>${money(g.cost)}</td><td>${number(g.quality,0)} / 100</td><td>${g.due?'Týden '+g.due:'Ve skladu'}</td></tr>`).join('')||'<tr><td colspan="5">Zelená zásoba je prázdná.</td></tr>'}</tbody></table></div></section><div class="section-header"><h2>Od plantáže ke kavárně · historie výroby</h2><span class="sub">Klikni na šarži pro cestu a skutečné odběry</span></div><section class="card"><div class="table-scroll"><table class="data"><thead><tr><th scope="col">Šarže / káva</th><th scope="col">Pražírna</th><th scope="col">Výroba / náklad</th><th scope="col">Vlastní původ</th><th scope="col">Report</th></tr></thead><tbody>${state.craft5.ledger.filter(x=>x.blend===b.id).slice(-30).reverse().map(x=>`<tr><td><strong>${esc(x.recipe.name)}</strong><small>T${x.week} · ${esc(x.id)}${x.purpose==='trial'?' · experiment':''}</small></td><td>${esc(x.roaster.name)}<small>${esc(x.roaster.city)}</small></td><td>${number(x.output,1)} kg<small>${money(x.unit)} / kg</small></td><td>${number(x.sources.filter(s=>s.source.known).reduce((a,s)=>a+s.kg,0)/x.input*100,0)} % zelených zrn</td><td><button class="soft mini" data-craft-trace="${x.id}">Otevřít cestu šarže</button></td></tr>`).join('')||'<tr><td colspan="5">Zatím žádná nová šarže této kávy. Starší zásoby nemají doplněný vymyšlený původ.</td></tr>'}</tbody></table></div></section>`;}
function craftReadProfile5(){return el('craftProfileEnabled5').checked?{drop:Number(el('craftDrop5').value),minutes:Number(el('craftMinutes5').value),development:Number(el('craftDevelopment5').value)}:null;}
function craftReadSources5(){return {primarySource:el('craftPrimary5').value,secondarySource:el('craftSecondary5').value,fallback:el('craftFallback5').checked};}
function craftPreviewDialog5(){const {b,r}=currentCraft5(),kg=Number(el('craftKg5').value),profile=craftReadProfile5(),sources=craftReadSources5();try{const proposed=craftPreview5(r.id,b.id,kg,profile,sources);let current=null,error='';try{current=craftPreview5(r.id,b.id,kg,roastProfile5(r,b));}catch(e){error=e.message;}const panel=(x,title)=>`<section class="card"><h3>${title}</h3>${x?`${rows([['Pražená káva',number(x.output,2)+' kg'],['Zpracování · platba',money(x.processing)],['Celkový náklad / kg',money(x.unit)],['Kvalita nové šarže',number(x.quality,1)+' / 100'],['Využití kapacity',number(x.effort,1)+' kg standardního profilu'],['Volná kapacita po šarži',number(x.freeCapacity,1)+' kg standardního profilu']])}${flavorBars5(x.flavor)}<p class="sub">Chuťové přijetí v herním modelu: ${Object.entries(x.fit).map(([k,n])=>SEGMENTS[k].name+' '+number((n-1)*100,1)+' %').join(' · ')}.</p>`:`<p>${esc(error)}</p>`}</section>`;show(`<h2>Porovnání · ${esc(b.name)}</h2><p class="sub">${kg} kg zelených zrn, dostupné zásoby a současná kapacita. Výsledek je odhad modelu nové šarže; náhled nic nevyrobil ani nezaplatil.</p><div class="split">${panel(current,'Uložené nastavení')}${panel(proposed,'Návrh ve formuláři')}</div><p class="sub">Původ návrhu: ${proposed.sources.map(s=>number(s.kg,1)+' kg '+esc(sourceLabel5(s.source))).join(' · ')}. Teplota, čas a development se použijí po uložení profilu; původy ulož samostatně.</p>`);}catch(e){toast(e.message);}}
function craftRoastDialog5(){const {b,r}=currentCraft5(),kg=Number(el('craftKg5').value);try{if(JSON.stringify(craftReadProfile5())!==JSON.stringify(roastProfile5(r,b))||JSON.stringify(craftReadSources5())!==JSON.stringify(craftSourcing5(b)))throw Error('Nejdřív ulož změněný profil a pravidla původu.');const quote=craftPreview5(r.id,b.id,kg,roastProfile5(r,b));confirmAction('Vyrobit šarži '+esc(b.name)+'?','Zelená káva '+kg+' kg → '+number(quote.output,2)+' kg pražené. Zpracování '+money(quote.processing)+', celkový náklad zásoby '+money(quote.unit)+'/kg. Výroba spotřebuje zrna a kapacitu pražírny.',()=>roastCraftConfirmed5(r.id,b.id,kg,quote),'Vyrobit šarži');}catch(e){toast(e.message);}}
function craftTraceDialog5(id){const x=craftTraceReport5(id);if(!x)return;const alive=x.stock+x.transit+x.trial;show(`<span class="eyelabel">CESTA KONKRÉTNÍ ŠARŽE · ${esc(x.id)}</span><h2>${esc(x.recipe.name)}</h2><div class="craft-journey5"><div><strong>01 · Sklizeň / zásoby</strong><p>${x.sources.map(s=>number(s.kg,2)+' kg · '+esc(sourceLabel5(s.source))+(s.source.known?' · sklizeň T'+s.source.harvested:'')).join('<br>')}</p></div><div><strong>02 · Pražení</strong><p>${esc(x.roaster.name)} · ${esc(x.roaster.city)} · T${x.week}<br>${number(x.input,2)} → ${number(x.output,2)} kg · ${x.profile?x.profile.drop+' °C / '+x.profile.minutes+' min / '+x.profile.development+' %':'profil receptury'}<br>Zpracování ${money(x.processing)}, náklad ${money(x.unit)} / kg</p></div><div><strong>03 · Prodej & zásoba</strong><p>Spotřebováno ${number(x.consumed,2)} kg<br>Sklad ${number(x.stock,2)} kg · na cestě ${number(x.transit,2)} kg · experiment ${number(x.trial,2)} kg<br>Odepsáno ${number(x.writtenOff,2)} kg</p></div></div>${flavorBars5(x.flavor)}<h3>Skutečné odběry této šarže</h3>${x.deliveries.length?`<div class="table-scroll"><table class="data"><thead><tr><th scope="col">Kam káva šla</th><th scope="col">Množství</th><th scope="col">Týdny</th></tr></thead><tbody>${x.deliveries.map(d=>`<tr><td>${esc(d.label)}<small>${d.kind==='store'?'Kavárna':d.kind==='eshop'?'E-shop':'Obchod'}</small></td><td>${number(d.kg,2)} kg</td><td>${d.first}–${d.last}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sub">Tato šarže zatím neměla zaznamenaný odběr.</p>'}<p class="sub">Výroba ${number(x.output,2)} kg = spotřeba ${number(x.consumed,2)} kg + dostupná šarže ${number(alive,2)} kg + odpis ${number(x.writtenOff,2)} kg. Zaznamenané zpracování, receptura a chuť se další změnou plánu nepřepíší.</p>`);}
function estateCraftCards5(){return `<div class="section-header"><h2>Odrůdy & zpracování vlastní sklizně</h2><button class="soft" data-goto="craft">Šarže, původ & pražení</button></div><div class="cards">${state.estates.map(e=>{const p=e.craft5,variety=VARIETIES5[p.variety],process=PROCESSES5[p.process];return `<section class="card"><div class="card-head"><h3>${esc(e.name)}</h3><span class="badge">${esc(e.country)}</span></div><div class="fields">${field('Odrůda porostu',`<select data-estate-variety="${e.id}">${ORIGIN_VARIETIES5[e.origin].map(k=>option(k,VARIETIES5[k].name,p.variety)).join('')}</select>`)}${field('Zpracování sklizně',`<select data-estate-process="${e.id}">${Object.entries(PROCESSES5).map(([k,x])=>option(k,x.name,p.process)).join('')}</select>`)}${field('Fermentace (hodiny)',`<input type="number" min="0" max="72" value="${p.hours}" data-estate-hours="${e.id}">`)}</div>${rows([['Výnos proti původnímu porostu',number(estateYield5(e)*100,0)+' %'],['Kvalita proti původnímu původu',(estateQuality5(e)>=0?'+':'')+number(estateQuality5(e),1)],['Pěstování navíc / týden',money(variety.upkeep)],['Zpracování sklizně',money(process.cost)+' / kg'],['Zpracování + doprava',2+process.weeks+' týdnů']])}<button class="primary" data-estate-craft-save="${e.id}">Prověřit a potvrdit změnu</button><p class="sub">Změna odrůdy znamená novou výsadbu, obnoví celý sklizňový cyklus a odepíše předchozí rozpracovanou sklizeň. Technologie zpracování se pořizuje jednou; za zpracování platíš při každé sklizni. Původní / natural mají 0 hodin, cílová fermentace: promyté 12, honey 24, řízená 48 hodin. Delší fermentace může kvalitu snížit. Parametry jsou herní model.</p></section>`}).join('')||empty('Kup plantáž a získej kontrolu nad odrůdou i zpracováním sklizně.')}</div>`;}
function estateCraftDialog5(id){const data={variety:document.querySelector(`[data-estate-variety="${id}"]`).value,process:document.querySelector(`[data-estate-process="${id}"]`).value,hours:Number(document.querySelector(`[data-estate-hours="${id}"]`).value)};try{const q=estatePlanQuote5(id,data),e=state.estates.find(e=>e.id===id);confirmAction('Změnit pěstování '+esc(e.name)+'?','Cena '+money(q.cost)+'. '+(q.replant?'Nová výsadba obnoví cyklus na '+e.period+' týdnů a odepíše '+money(q.writeoff)+' rozpracované sklizně.':'Zpracování platí od příští sklizně. ')+(q.setup?' Technologie zpracování '+money(q.setup)+' je v ceně.':''),()=>setEstatePlan5(id,data,q),'Potvrdit změnu');}catch(e){toast(e.message);}}
coffeeView=function(){return `<div class="actions"><button class="primary" data-goto="craft">Vlastní původ, pražicí profily & cesta šarže</button></div><p class="sub">Kvalita receptury odhaduje běžná zrna; skutečnou kvalitu a náklad vlastní sklizně s pražicím profilem najdeš v reportu vyrobené šarže.</p>`+CRAFT_UI5.coffeeView();};
roastersView=function(){return `<div class="actions"><button class="primary" data-goto="craft">Individuální profily & historie šarží</button></div><p class="sub">Kapacita je vyjádřená pro standardní dvanáctiminutový profil. Delší profily zabírají více směny; report zaznamenává skutečná zelená zrna i výstup.</p>`+CRAFT_UI5.roastersView();};
estatesView=function(){return estateCraftCards5()+CRAFT_UI5.estatesView();};
labView=function(){return `<div class="actions"><button class="soft" data-goto="craft">Původ a profil experimentální kávy</button></div><p class="sub">Experiment použije také uložený profil vybrané pražírny a pravidla původu dané kávy. Individuální profil určuje skutečný stupeň pražení.</p>`+CRAFT_UI5.labView();};
performanceView=function(){return `<div class="actions"><button class="soft" data-goto="craft">Report šarží · od sklizně k odběrateli</button></div>`+CRAFT_UI5.performanceView();};
supplyView=function(){return CRAFT_UI5.supplyView().replace('a 55 Kč zpracování / kg zelené kávy.','a skutečnou cenu zpracování profilu (od 55 Kč / kg zelené kávy).');};
bind=function(){CRAFT_UI5.bind();if(el('craftBlend5'))el('craftBlend5').onchange=()=>{craftBlend5=el('craftBlend5').value;render()};if(el('craftRoaster5'))el('craftRoaster5').onchange=()=>{craftRoaster5=el('craftRoaster5').value;render()};if(el('craftSourcesSave5'))el('craftSourcesSave5').onclick=()=>act(()=>setCoffeeSources5(currentCraft5().b.id,craftReadSources5()),'Pravidla původu uložena.');if(el('craftProfileSave5'))el('craftProfileSave5').onclick=()=>act(()=>{const {b,r}=currentCraft5();setRoastProfile5(r.id,b.id,craftReadProfile5());},'Profil uložen; hotové šarže se nemění.');if(el('craftProfileReset5'))el('craftProfileReset5').onclick=()=>act(()=>{const {b,r}=currentCraft5();setRoastProfile5(r.id,b.id,null);},'Použije se původní profil receptury.');if(el('craftPreview5'))el('craftPreview5').onclick=craftPreviewDialog5;if(el('craftRoast5'))el('craftRoast5').onclick=craftRoastDialog5;on('[data-craft-trace]',b=>craftTraceDialog5(b.dataset.craftTrace));on('[data-estate-craft-save]',b=>estateCraftDialog5(b.dataset.estateCraftSave));};
help=function(){CRAFT_UI5.help();const p=document.createElement('p');p.textContent='Vlastní původ & pražení: na plantážích zvol odrůdu a zpracování. Nová výsadba obnoví cyklus a odepíše rozpracovanou sklizeň. Zpracování přidává cenu i dobu dodání. Ve vlastní kávě můžeš vyžadovat konkrétní plantáž, nebo dovolit náhradní zrna. Každá pražírna má samostatné profily pro jednotlivé kávy; náhled použije kopii hry bez výdaje. Uložená teplota, čas a development ovlivní nové pražení. Cesta šarže ukazuje skutečně použité sklizně, náklady, odběry, zásobu a odpisy. Starší šarže nemají doplněné vymyšlené detaily původu.';el('modalContent').append(p);};el('help').onclick=help;
render();
